const src={"backend/lib/billing/billingOperations.js": "'use strict';\n\n// A local application maintenance gate, not a replacement for draining old\n// instances/in-flight provider requests before a financial release is paused.\n// Missing configuration preserves incumbent behavior. An explicitly configured\n// but invalid value must never enable money movement accidentally.\nfunction billingOperationsEnabled(env = process.env) {\n    if (env.BILLING_OPERATIONS_ENABLED === undefined) return true;\n    return ['true', '1'].includes(String(env.BILLING_OPERATIONS_ENABLED).trim().toLowerCase());\n}\n\nfunction assertBillingOperationsEnabled(env = process.env) {\n    if (billingOperationsEnabled(env)) return;\n    throw Object.assign(new Error('שירות התשלום מושהה כרגע. נסו שוב מאוחר יותר.'), {\n        code: 'BILLING_OPERATIONS_PAUSED', httpStatus: 503, status: 503, retryAfter: 60,\n    });\n}\n\nfunction isBillingOperationsPausedError(error) {\n    return error?.code === 'BILLING_OPERATIONS_PAUSED';\n}\n\nfunction respondIfBillingPaused(res, error) {\n    if (!isBillingOperationsPausedError(error)) return false;\n    res.setHeader('Retry-After', String(error.retryAfter || 60));\n    res.status(503).json({ error: error.code, errorCode: error.code, message: error.message });\n    return true;\n}\n\nmodule.exports = { billingOperationsEnabled, assertBillingOperationsEnabled, isBillingOperationsPausedError, respondIfBillingPaused };\n", "backend/lib/billing/pricingPackage.js": "/**\n * Commercial package catalog — keep in sync with\n * frontend/src/components/pricing/pricingConfig.js\n */\n\nconst PRICING = {\n    currency: 'ILS',\n    system: { id: 'system', label: 'מערכת', amount: 296 },\n    platforms: [\n        { id: 'none', label: 'ללא', amount: 0 },\n        { id: 'site', label: 'אתר', amount: 152 },\n        { id: 'app', label: 'אפליקציה', amount: 194 },\n        { id: 'site_app', label: 'אתר + אפליקציה', amount: 296 },\n    ],\n    resources: [\n        { id: 'basic', label: 'בסיסי', amount: 84, storageMb: 250, usersQuota: 2, planKey: 'BASIC' },\n        { id: 'pro', label: 'פרו', amount: 211, storageMb: 1024, usersQuota: 5, planKey: 'PRO' },\n        { id: 'enterprise', label: 'ארגוני', amount: 592, storageMb: null, usersQuota: null, planKey: 'ENTERPRISE' },\n    ],\n    signing: [\n        { id: 'none', label: 'ללא חתימות', amount: 0, includedSignatures: 0 },\n        { id: '500', label: '500 חתימות', amount: 169, includedSignatures: 500 },\n        { id: '1500', label: '1500 חתימות', amount: 338, includedSignatures: 1500 },\n        { id: '5000', label: '5000 חתימות', amount: 677, includedSignatures: 5000 },\n        { id: 'unlimited', label: 'חתימות ללא הגבלה', amount: 1101, includedSignatures: null },\n    ],\n};\n\n/** SMS monthly caps by resource pack. Enterprise is capped (not unlimited). */\nconst RESOURCE_SMS_MONTHLY_QUOTA = {\n    basic: 200,\n    pro: 2000,\n    enterprise: 5000,\n};\n\nconst DEFAULT_SELECTION = {\n    platformId: 'site_app',\n    resourceId: 'pro',\n    signingId: '500',\n};\n\nconst YEARLY_DISCOUNT_RATE = 0.10;\n\nfunction normalizeBillingInterval(value) {\n    return String(value || '').trim().toLowerCase() === 'yearly' ? 'yearly' : 'monthly';\n}\n\nfunction yearlyTotalIls(monthlyAmount) {\n    const monthly = Number(monthlyAmount || 0);\n    if (!Number.isFinite(monthly) || monthly <= 0) return 0;\n    return Math.round(monthly * 12 * (1 - YEARLY_DISCOUNT_RATE));\n}\n\nfunction yearlySavingsIls(monthlyAmount) {\n    const monthly = Number(monthlyAmount || 0);\n    if (!Number.isFinite(monthly) || monthly <= 0) return 0;\n    return Math.round(monthly * 12) - yearlyTotalIls(monthly);\n}\n\nfunction findById(list, id, fallbackId) {\n    return list.find((x) => x.id === id) || list.find((x) => x.id === fallbackId) || list[0];\n}\n\nfunction resolvePricingLineItems({ platformId, resourceId, signingId } = {}) {\n    const platform = findById(PRICING.platforms, platformId, DEFAULT_SELECTION.platformId);\n    const resource = findById(PRICING.resources, resourceId, DEFAULT_SELECTION.resourceId);\n    const signing = findById(PRICING.signing, signingId, DEFAULT_SELECTION.signingId);\n    const system = PRICING.system;\n\n    const breakdown = [\n        { id: 'system', label: system.label, amount: Number(system.amount || 0) },\n        { id: 'platform', label: `פלטפורמה: ${platform.label}`, amount: Number(platform.amount || 0) },\n        { id: 'resources', label: `חבילת משאבים: ${resource.label}`, amount: Number(resource.amount || 0) },\n        { id: 'signing', label: `חבילת חתימות: ${signing.label}`, amount: Number(signing.amount || 0) },\n    ];\n    const total = breakdown.reduce((sum, it) => sum + Number(it.amount || 0), 0);\n\n    return {\n        platformId: platform.id,\n        resourceId: resource.id,\n        signingId: signing.id,\n        system,\n        platform,\n        resource,\n        signing,\n        breakdown,\n        total,\n        yearlyTotal: yearlyTotalIls(total),\n        yearlySavings: yearlySavingsIls(total),\n        currency: PRICING.currency,\n        displayName: `${resource.label} · ${platform.label} · ${signing.label}`,\n    };\n}\n\nfunction quotasForPackage({ resourceId, signingId } = {}) {\n    const resource = findById(PRICING.resources, resourceId, DEFAULT_SELECTION.resourceId);\n    const signing = findById(PRICING.signing, signingId, DEFAULT_SELECTION.signingId);\n    const storageMb = resource.storageMb;\n    return {\n        planKey: resource.planKey,\n        planName: resource.label,\n        documentsMonthlyQuota: signing.includedSignatures,\n        storageMbQuota: storageMb,\n        usersQuota: resource.usersQuota,\n        otpSmsMonthlyQuota: Object.prototype.hasOwnProperty.call(RESOURCE_SMS_MONTHLY_QUOTA, resource.id)\n            ? RESOURCE_SMS_MONTHLY_QUOTA[resource.id]\n            : null,\n        storageBytesQuota:\n            storageMb == null ? null : Number(storageMb) * 1024 * 1024,\n    };\n}\n\nfunction platformRank(platformId) {\n    const id = String(platformId || '');\n    if (id === 'site_app') return 2;\n    if (id === 'site' || id === 'app') return 1;\n    return 0;\n}\n\nfunction quotaExceeded(used, quota) {\n    if (quota === null || quota === undefined) return false;\n    const q = Number(quota);\n    if (!Number.isFinite(q) || q < 0) return false;\n    const u = Number(used || 0);\n    return u > q;\n}\n\nconst SIGNING_FLOOR_ID = '500';\n\nfunction signingRank(signingId) {\n    const idx = PRICING.signing.findIndex((s) => s.id === signingId);\n    return idx < 0 ? 0 : idx;\n}\n\n/**\n * Cheapest pack that fits current usage.\n * Platform stays as-is (already deployed). Signing never drops below 500.\n * Resource considers seats, storage, and SMS volume.\n */\nfunction recommendCheapestPackage({ current, usage } = {}) {\n    const cur = resolvePricingLineItems(current || DEFAULT_SELECTION);\n    const platformId = cur.platformId;\n    const smsUsed = Number(usage?.sms?.sentThisMonth || 0);\n\n    let resourceId = 'enterprise';\n    for (const resource of PRICING.resources) {\n        const ev = evaluatePackageChange({\n            current: cur,\n            next: { platformId, resourceId: resource.id, signingId: cur.signingId },\n            usage,\n        });\n        const smsOk = !quotaExceeded(smsUsed, RESOURCE_SMS_MONTHLY_QUOTA[resource.id]);\n        if (ev.allowed && smsOk) {\n            resourceId = resource.id;\n            break;\n        }\n    }\n\n    const floorRank = signingRank(SIGNING_FLOOR_ID);\n    let signingId = 'unlimited';\n    for (const signing of PRICING.signing) {\n        if (signingRank(signing.id) < floorRank) continue;\n        const ev = evaluatePackageChange({\n            current: cur,\n            next: { platformId, resourceId, signingId: signing.id },\n            usage,\n        });\n        if (ev.allowed) {\n            signingId = signing.id;\n            break;\n        }\n    }\n\n    const recommended = resolvePricingLineItems({ platformId, resourceId, signingId });\n    return {\n        current: cur,\n        recommended,\n        changed:\n            cur.platformId !== recommended.platformId\n            || cur.resourceId !== recommended.resourceId\n            || cur.signingId !== recommended.signingId,\n    };\n}\n\n/**\n * Cheaper resource/signing packs are blocked when current usage would not fit.\n * Platform add-on cannot be decreased (already deployed).\n */\nfunction evaluatePackageChange({ current, next, usage } = {}) {\n    const cur = resolvePricingLineItems(current || {});\n    const nxt = resolvePricingLineItems(next || {});\n    const nextQuotas = quotasForPackage(nxt);\n    const blocks = [];\n    if (!['site', 'app', 'site_app'].includes(next?.platformId)) {\n        blocks.push({ field: 'platformId', message: 'יש לבחור אתר, אפליקציה או אתר ואפליקציה. אין חבילה ללא פלטפורמה.' });\n    }\n\n    if (platformRank(nxt.platformId) < platformRank(cur.platformId)) {\n        blocks.push({\n            field: 'platformId',\n            message: 'לא ניתן להוריד את חבילת האתר/האפליקציה — היא כבר פרוסה אצלכם.',\n        });\n    }\n\n    const docsUsed = Number(usage?.documents?.createdThisMonth || 0);\n    const seatsUsed = Number(usage?.seats?.used || 0);\n    const storageBytes = Number(usage?.storage?.bytesTotal || 0);\n    const smsUsed = Number(usage?.sms?.sentThisMonth || 0);\n\n    if (quotaExceeded(docsUsed, nextQuotas.documentsMonthlyQuota)) {\n        blocks.push({\n            field: 'signingId',\n            message: `לא ניתן לרדת בחבילת החתימות: השתמשתם ב-${docsUsed} מסמכים החודש, והחבילה כוללת ${nextQuotas.documentsMonthlyQuota}.`,\n        });\n    }\n    if (quotaExceeded(seatsUsed, nextQuotas.usersQuota)) {\n        blocks.push({\n            field: 'resourceId',\n            message: `לא ניתן לרדת בחבילת המשאבים: יש ${seatsUsed} מנהלי מערכת, והחבילה מאפשרת ${nextQuotas.usersQuota}.`,\n        });\n    }\n    if (quotaExceeded(storageBytes, nextQuotas.storageBytesQuota)) {\n        const usedMb = (storageBytes / (1024 * 1024)).toFixed(1);\n        blocks.push({\n            field: 'resourceId',\n            message: `לא ניתן לרדת בחבילת המשאבים: בשימוש ${usedMb} MB, והחבילה כוללת ${nextQuotas.storageMbQuota} MB.`,\n        });\n    }\n    if (quotaExceeded(smsUsed, nextQuotas.otpSmsMonthlyQuota)) {\n        blocks.push({\n            field: 'resourceId',\n            message: `לא ניתן לרדת בחבילת המשאבים: נשלחו ${smsUsed} SMS החודש, והחבילה כוללת ${nextQuotas.otpSmsMonthlyQuota}.`,\n        });\n    }\n\n    return {\n        allowed: blocks.length === 0,\n        blocks,\n        current: cur,\n        next: nxt,\n        nextQuotas,\n        priceIncreased: nxt.total > cur.total,\n        priceDecreased: nxt.total < cur.total,\n    };\n}\n\nfunction disabledOptionsForUsage({ current, usage } = {}) {\n    const cur = resolvePricingLineItems(current || {});\n    const resourceIds = [];\n    const signingIds = [];\n    const platformIds = [];\n\n    for (const p of PRICING.platforms) {\n        const ev = evaluatePackageChange({\n            current: cur,\n            next: { ...cur, platformId: p.id },\n            usage,\n        });\n        if (!ev.allowed) platformIds.push(p.id);\n    }\n    for (const r of PRICING.resources) {\n        const ev = evaluatePackageChange({\n            current: cur,\n            next: { ...cur, resourceId: r.id },\n            usage,\n        });\n        if (!ev.allowed) resourceIds.push(r.id);\n    }\n    for (const s of PRICING.signing) {\n        const ev = evaluatePackageChange({\n            current: cur,\n            next: { ...cur, signingId: s.id },\n            usage,\n        });\n        if (!ev.allowed) signingIds.push(s.id);\n    }\n\n    return { platformIds, resourceIds, signingIds };\n}\n\nmodule.exports = {\n    PRICING,\n    DEFAULT_SELECTION,\n    RESOURCE_SMS_MONTHLY_QUOTA,\n    YEARLY_DISCOUNT_RATE,\n    normalizeBillingInterval,\n    yearlyTotalIls,\n    yearlySavingsIls,\n    resolvePricingLineItems,\n    quotasForPackage,\n    platformRank,\n    evaluatePackageChange,\n    disabledOptionsForUsage,\n    recommendCheapestPackage,\n};\n", "backend/lib/billing/signupQuote.js": "'use strict';\nconst { PRICING, resolvePricingLineItems } = require('./pricingPackage');\nconst CONSENT_VERSION = 'signup-1ils-3months-v2';\nconst SUPPORTED_CONSENT_VERSIONS = ['signup-1ils-3months-v1', CONSENT_VERSION];\n// Owner-confirmed 2026-10-12: legal catalogue amounts are final, no VAT added.\nconst VAT_PERCENT = 0;\n\nfunction quoteSignup(selection = {}) {\n    if (!['site', 'app', 'site_app'].includes(selection.platformId)) {\n        throw Object.assign(new Error('יש לבחור אתר, אפליקציה או שניהם'), { code: 'INVALID_PACKAGE' });\n    }\n    for (const [key, choices] of [['platformId', PRICING.platforms], ['resourceId', PRICING.resources], ['signingId', PRICING.signing]]) {\n        if (!choices.some(option => option.id === selection[key])) {\n            throw Object.assign(new Error('יש לבחור חבילה תקינה במחירון'), { code: 'INVALID_PACKAGE' });\n        }\n    }\n    if (!['monthly', 'yearly'].includes(selection.billingInterval)) {\n        throw Object.assign(new Error('יש לבחור תדירות חיוב תקינה'), { code: 'INVALID_PACKAGE' });\n    }\n    const pkg = resolvePricingLineItems(selection);\n    const net = selection.billingInterval === 'yearly' ? pkg.yearlyTotal : pkg.total;\n    // Keep the established annual rounding; never add tax to this final-price catalogue.\n    return { ...pkg, netAmountIls: net, recurringAmountIls: Math.round(net * (100 + VAT_PERCENT)) / 100, vatPercent: VAT_PERCENT };\n}\n\nfunction renewalAmount(account, consent) {\n    // Existing contracts retain their agreed amounts. New quotes freeze the final charge.\n    if (consent?.consent_version === CONSENT_VERSION) {\n        const amount = Number(consent.recurring_amount_ils);\n        if (!Number.isFinite(amount) || amount <= 0) throw new Error('SIGNUP_BILLING_AMOUNT_REQUIRED');\n        // The billing row stores the agreed price, never a live catalogue lookup.\n        // An explicitly accepted later plan change must not keep charging the signup price.\n        if (account.price_monthly_ils != null) {\n            const monthly = Number(account.price_monthly_ils);\n            if (!Number.isFinite(monthly) || monthly <= 0) throw new Error('SIGNUP_BILLING_AMOUNT_REQUIRED');\n            return account.billing_interval === 'yearly' ? Math.round(monthly * 12 * 0.9) : monthly;\n        }\n        return amount;\n    }\n    return account.billing_interval === 'yearly'\n        ? Math.round(Number(account.price_monthly_ils) * 12 * 0.9)\n        : Number(account.price_monthly_ils);\n}\nmodule.exports = { CONSENT_VERSION, SUPPORTED_CONSENT_VERSIONS, quoteSignup, renewalAmount };\n", "backend/lib/billing/calendarMonths.js": "'use strict';\nfunction addIsraelCalendarMonths(from,months) {\n    const date=new Date(from);\n    if(!Number.isFinite(date.getTime())||!Number.isInteger(months))throw Error('INVALID_CALENDAR_DATE');\n    const formatter=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jerusalem',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'});\n    const wall=value=>{\n        const p=Object.fromEntries(formatter.formatToParts(value).map(x=>[x.type,x.value]));\n        return new Date(Date.UTC(Number(p.year),Number(p.month)-1,Number(p.day),Number(p.hour),Number(p.minute),Number(p.second)));\n    };\n    const target=wall(date),day=target.getUTCDate();target.setUTCDate(1);target.setUTCMonth(target.getUTCMonth()+months);\n    target.setUTCDate(Math.min(day,new Date(Date.UTC(target.getUTCFullYear(),target.getUTCMonth()+1,0)).getUTCDate()));\n    let candidate=target.getTime();const seen=[];\n    for(let n=0;n<5;n++){\n        const delta=target.getTime()-wall(new Date(candidate)).getTime();\n        if(delta===0)return new Date(candidate+date.getUTCMilliseconds());\n        candidate+=delta;\n        if(seen.includes(candidate))return new Date(Math.max(...seen,candidate)+date.getUTCMilliseconds()); // DST gap: after the gap.\n        seen.push(candidate);\n    }\n    throw Error('INVALID_CALENDAR_TIME');\n}\nmodule.exports={addIsraelCalendarMonths};\n", "backend/lib/payments/verifySignupPayment.js": "'use strict';\nconst { assertBillingOperationsEnabled } = require('../billing/billingOperations');\n\n// Provider reads bind a hosted order to its approved card transaction. Callback\n// fields and ValidateNotification alone are not the card/transaction authority.\nasync function verifyHostedPayment(credentials, reference, expectedOrder, amount, fetcher=fetch, requireToken=false) {\n    assertBillingOperationsEnabled();\n    if (!reference || !expectedOrder || !Number.isFinite(amount) || amount <= 0) throw Error('PAYMENT_VERIFICATION_REQUIRED');\n    const read = async (name, query) => {\n        assertBillingOperationsEnabled();\n        const response=await fetcher('https://api.takbull.co.il/api/ExtranalAPI/'+name+'?'+new URLSearchParams(query), {\n            headers:{API_Key:credentials.apiKey,API_Secret:credentials.apiSecret},\n            signal:AbortSignal.timeout(20000),redirect:'error',\n        });\n        if(!response.ok)throw new Error('SIGNUP_PROVIDER_UNAVAILABLE');\n        return response.json();\n    };\n    const order=await read('GetOrder',{orderUniqId:reference});\n    if(order.uniqId!==reference || order.order_reference!==expectedOrder || order.currency!=='ILS' || Number(order.orderTotalSum)!==amount || Number(order.orderStatus)!==3)\n        throw new Error('SIGNUP_PAYMENT_IDENTITY_MISMATCH');\n    const approved=(Array.isArray(order.transactions)?order.transactions:[]).filter(t=>t&&Number(t.status)===1);\n    if(approved.length!==1||Number(approved[0].amount)!==amount||!approved[0].transactionId)throw new Error('SIGNUP_PAYMENT_IDENTITY_MISMATCH');\n    const id=String(approved[0].transactionId),t=await read('GetTransaction',{transactionInternalNumber:id});\n    if(String(t.transactionId)!==id||t.currency!=='ILS'||Number(t.amount)!==amount||Number(t.status)!==1||t.statusCode==null||Number(t.statusCode)!==0||Number(t.transactionType)!==10||Number(t.paymentMethod)!==3)\n        throw new Error('SIGNUP_PAYMENT_IDENTITY_MISMATCH');\n    const validToken = typeof t.cardToken==='string' && Boolean(t.cardToken) && t.cardToken.length<=4096;\n    if (requireToken && !validToken) throw new Error('SIGNUP_PAYMENT_TOKEN_REQUIRED');\n    return {transactionId:id,tokenInfo:validToken ? {token:t.cardToken,last4Digits:/^\\d{4}$/.test(t.last4DigitsCardNumber||'')?t.last4DigitsCardNumber:null,\n        expMonth:t.cardTokenExpirationMonth||null,expYear:t.cardTokenExpirationYear||null,cardBrand:t.cardtype||null} : null};\n}\nasync function verifySignupPayment(credentials, reference, expectedOrder, fetcher=fetch) {\n    assertBillingOperationsEnabled();\n    return verifyHostedPayment(credentials, reference, expectedOrder, 1, fetcher, true);\n}\nasync function verifyChargedTransaction(credentials,id,amount,fetcher=fetch){\n    assertBillingOperationsEnabled();\n    const response=await fetcher('https://api.takbull.co.il/api/ExtranalAPI/GetTransaction?'+new URLSearchParams({transactionInternalNumber:id}),{\n        headers:{API_Key:credentials.apiKey,API_Secret:credentials.apiSecret},signal:AbortSignal.timeout(20000),redirect:'error'});\n    if(!response.ok)throw Error('RENEWAL_PROVIDER_UNAVAILABLE');\n    const t=await response.json();\n    if(String(t.transactionId)!==String(id)||t.currency!=='ILS'||Number(t.amount)!==amount||Number(t.status)!==1||t.statusCode==null||Number(t.statusCode)!==0||Number(t.transactionType)!==10||Number(t.paymentMethod)!==3)\n        throw Error('RENEWAL_PAYMENT_IDENTITY_MISMATCH');\n    return true;\n}\nmodule.exports={verifySignupPayment,verifyChargedTransaction,verifyHostedPayment};\n", "backend/lib/payments/takbullClient.js": "const { assertBillingOperationsEnabled } = require('../billing/billingOperations');\n/**\n * Takbull External API client (sandbox + production share the same host).\n * Ported from Melamotion for LayerWebsites firm billing.\n * Docs: https://api.takbull.co.il/ApiDocs\n */\n\nconst TAKBULL_API_BASE = 'https://api.takbull.co.il';\nconst TAKBULL_PAYMENT_GATEWAY = `${TAKBULL_API_BASE}/PaymentGateway`;\n\nfunction asRecord(value) {\n    return value && typeof value === 'object' && !Array.isArray(value) ? value : {};\n}\n\nfunction requireCreds(credentials) {\n    const apiKey = typeof credentials?.apiKey === 'string' ? credentials.apiKey.trim() : '';\n    const apiSecret = typeof credentials?.apiSecret === 'string' ? credentials.apiSecret.trim() : '';\n    if (!apiKey || !apiSecret) {\n        throw new Error('Takbull credentials require apiKey and apiSecret.');\n    }\n    return { apiKey, apiSecret };\n}\n\nfunction authHeaders(creds) {\n    return {\n        'Content-Type': 'application/json',\n        API_Key: creds.apiKey,\n        API_Secret: creds.apiSecret,\n    };\n}\n\nfunction pickStringField(record, keys) {\n    for (const key of keys) {\n        const v = record[key];\n        if (typeof v === 'string' && v.trim()) return v.trim();\n        if (typeof v === 'number' && Number.isFinite(v)) return String(v);\n    }\n    return null;\n}\n\n// Ask Takbull to create the payment document as part of the single payment\n// operation. Never issue a second DocumentApi/Create request after a timeout:\n// that endpoint has no documented idempotency contract. The merchant's existing\n// document/tax/email settings remain authoritative unless explicitly overridden.\nfunction paymentDocumentOptions(input) {\n    const createDocument = input.createDocument !== false;\n    if (!createDocument) return { CreateDocument: false };\n    const configuredType = input.documentType ?? process.env.TAKBULL_DOCUMENT_TYPE;\n    if (configuredType == null || String(configuredType).trim() === '') return { CreateDocument: true };\n    const documentType = Number(configuredType);\n    if (![320, 400].includes(documentType)) {\n        throw new Error('TAKBULL_DOCUMENT_TYPE must be 320 (tax invoice/receipt) or 400 (receipt).');\n    }\n    return { CreateDocument: true, DocumentType: documentType };\n}\n\nfunction applyCustomer(body, input) {\n    if (!input.customerFullName && !input.customerPhone && !input.customerEmail && !input.customerAddress) return;\n    body.CustomerFullName = input.customerFullName || undefined;\n    body.CustomerPhoneNumber = input.customerPhone || undefined;\n    const address = asRecord(input.customerAddress);\n    body.Customer = {\n        CustomerFullName: input.customerFullName || undefined,\n        PhoneNumber: input.customerPhone || undefined,\n        Email: input.customerEmail || undefined,\n        ...(input.customerAddress ? { Address: {\n            Address1: address.address1 || undefined,\n            Address2: address.address2 || undefined,\n            City: address.city || undefined,\n            Country: address.country || undefined,\n            Zip: address.zip || undefined,\n        } } : {}),\n    };\n}\n\nfunction extractTakbullDocument(raw) {\n    const rec = asRecord(raw);\n    const id = pickStringField(rec, ['documentId', 'DocumentId', 'invoiceId', 'InvoiceId']);\n    const uniqId = pickStringField(rec, ['invoiceUniqId', 'InvoiceUniqId', 'documentUniqId', 'DocumentUniqId']);\n    const number = pickStringField(rec, ['documentNumber', 'DocumentNumber']);\n    const hasReference = Boolean((id && id !== '0') || uniqId || (number && number !== '0'));\n    return {\n        created: rec.isDocumentCreated === true || hasReference ? true : (rec.isDocumentCreated === false ? false : null),\n        id: id && id !== '0' ? id : null,\n        uniqId,\n        number: number && number !== '0' ? number : null,\n        // A document reference is not an email delivery acknowledgment.\n        deliveryStatus: 'unknown',\n    };\n}\n\nfunction requirePositiveAmount(input) {\n    if (!Number.isFinite(Number(input.amount)) || Number(input.amount) <= 0) {\n        throw new Error('Takbull payment amount must be positive.');\n    }\n}\n\nasync function isConfirmedFailedTransaction(input, transactionId) {\n    assertBillingOperationsEnabled();\n    if (!transactionId) return false;\n    try {\n        const response = await fetch(`${TAKBULL_API_BASE}/api/ExtranalAPI/GetTransaction?${new URLSearchParams({ transactionInternalNumber: transactionId })}`, {\n            headers: authHeaders(requireCreds(input.credentials)),\n            signal: AbortSignal.timeout(20000),\n            redirect: 'error',\n        });\n        if (!response.ok) return false;\n        const t = asRecord(await response.json());\n        // A failed document request can follow an approved charge. Only the\n        // matching terminal card transaction can permit a new payment attempt.\n        return String(t.transactionId) === transactionId\n            && t.currency === input.currency.toUpperCase()\n            && Number(t.amount) === Number(input.amount)\n            && Number(t.transactionType) === 10 && Number(t.paymentMethod) === 3\n            && [2, 6].includes(Number(t.status))\n            && t.statusCode != null && String(t.statusCode).trim() !== ''\n            && Number.isFinite(Number(t.statusCode)) && Number(t.statusCode) !== 0;\n    } catch (_) {\n        return false;\n    }\n}\n\nfunction paymentGatewayUrl(uniqId) {\n    return `${TAKBULL_PAYMENT_GATEWAY}?orderUniqId=${encodeURIComponent(uniqId)}`;\n}\n\nfunction isTakbullPaymentPaid(validated) {\n    if (!validated?.ok) return false;\n    if (validated.transactionStatusCode === 0) return true;\n    if (validated.orderStatus === 3) return true;\n    const statusRaw = validated.raw?.Status ?? validated.raw?.status;\n    if (typeof statusRaw === 'string' && statusRaw.trim().toLowerCase() === 'approved') return true;\n    const tx = asRecord(validated.raw?.transaction);\n    const txStatus = tx.status ?? tx.Status;\n    if (txStatus === 1 || txStatus === '1') return true;\n    return false;\n}\n\nfunction extractTokenFromValidated(raw) {\n    const rec = asRecord(raw);\n    const creditCard = asRecord(rec.CreditCard ?? rec.creditCard);\n    const token =\n        pickStringField(rec, ['token', 'Token', 'cardToken', 'CardToken']) ||\n        pickStringField(creditCard, ['CardExternalToken', 'cardExternalToken', 'token', 'Token']);\n    if (!token) return null;\n\n    const last4Digits =\n        pickStringField(rec, ['last4Digits', 'Last4Digits', 'last4DigitsCardNumber']) ||\n        pickStringField(creditCard, ['Last4Digits', 'last4Digits']);\n    const expMonth =\n        pickStringField(rec, ['TokenExpirationMonth', 'tokenExpirationMonth', 'cardTokenExpirationMonth']) ||\n        pickStringField(creditCard, ['CardTokenExpirationMonth', 'cardTokenExpirationMonth']);\n    const expYear =\n        pickStringField(rec, ['TokenExpirationYear', 'tokenExpirationYear', 'cardTokenExpirationYear']) ||\n        pickStringField(creditCard, ['CardTokenExpirationYear', 'cardTokenExpirationYear']);\n    const cardBrand =\n        pickStringField(rec, ['cardtype', 'cardType', 'CardType', 'cardBrand']) ||\n        pickStringField(creditCard, ['cardtype', 'CardType']);\n\n    return {\n        token,\n        last4Digits: last4Digits ? last4Digits.slice(-4) : null,\n        expMonth,\n        expYear,\n        cardBrand,\n    };\n}\n\nasync function createTakbullPaymentPage(input) {\n    assertBillingOperationsEnabled();\n    requirePositiveAmount(input);\n    const body = {\n        order_reference: input.orderReference,\n        OrderTotalSum: input.amount,\n        Currency: input.currency.toUpperCase() === 'ILS' ? 'ILS' : input.currency.toUpperCase(),\n        Language: 'he',\n        DealType: 1,\n        PaymentMethodType: 3,\n        DisplayType: input.returnMode === 'redirect' ? 'redirect' : 'iframe',\n        PostProcessMethod: input.returnMode === 'redirect' ? '0' : '1',\n        ...paymentDocumentOptions(input),\n        SaveToken: input.saveToken !== false,\n        RedirectAddress: input.redirectAddress,\n        CancelReturnAddress: input.cancelReturnAddress,\n        IPNAddress: input.ipnAddress,\n    };\n\n    if (input.purpose || body.CreateDocument) {\n        body.Products = [\n            {\n                SKU: String(input.orderReference).slice(0, 40),\n                ProductName: input.purpose || 'תשלום מנוי',\n                Description: input.purpose || 'תשלום מנוי',\n                Price: input.amount,\n                Quantity: 1,\n                CurrencyCode: body.Currency,\n            },\n        ];\n    }\n\n    applyCustomer(body, input);\n\n    const res = await fetch(`${TAKBULL_API_BASE}/api/ExtranalAPI/GetTakbullPaymentPageRedirectUrl`, {\n        method: 'POST',\n        headers: authHeaders(requireCreds(input.credentials)),\n        body: JSON.stringify(body),\n        signal: AbortSignal.timeout(20000),\n        redirect: 'error',\n    });\n\n    const raw = asRecord(await res.json().catch(() => ({})));\n    if (!res.ok) {\n        throw new Error(\n            `Takbull create payment page failed (${res.status}): ${\n                typeof raw.description === 'string' ? raw.description : res.statusText\n            }`\n        );\n    }\n\n    const uniqId = typeof raw.uniqId === 'string' ? raw.uniqId : '';\n    if (raw.responseCode !== 0 || !uniqId) {\n        const description =\n            typeof raw.description === 'string'\n                ? raw.description\n                : typeof raw.internalDescription === 'string'\n                    ? raw.internalDescription\n                    : 'Unknown Takbull error';\n        throw new Error(`Takbull create payment page rejected: ${description}`);\n    }\n\n    return { uniqId, redirectUrl: paymentGatewayUrl(uniqId), raw };\n}\n\nasync function validateTakbullNotification(credentials, uniqId) {\n    assertBillingOperationsEnabled();\n    const creds = requireCreds(credentials);\n    const res = await fetch(`${TAKBULL_API_BASE}/api/ExtranalAPI/ValidateNotification`, {\n        method: 'POST',\n        headers: authHeaders(creds),\n        body: JSON.stringify({ uniqId }),\n    });\n\n    const raw = asRecord(await res.json().catch(() => ({})));\n    if (!res.ok) {\n        return { ok: false, paid: false, internalDescription: `HTTP ${res.status}`, raw };\n    }\n\n    const internalCode =\n        typeof raw.internalCode === 'number'\n            ? raw.internalCode\n            : typeof raw.InternalCode === 'number'\n                ? raw.InternalCode\n                : undefined;\n    const internalDescription =\n        typeof raw.internalDescription === 'string'\n            ? raw.internalDescription\n            : typeof raw.InternalDescription === 'string'\n                ? raw.InternalDescription\n                : undefined;\n    const transactionStatus =\n        typeof raw.tranSactionStatus === 'number'\n            ? raw.tranSactionStatus\n            : typeof raw.transactionStatus === 'number'\n                ? raw.transactionStatus\n                : undefined;\n    const orderStatus = typeof raw.orderStatus === 'number' ? raw.orderStatus : undefined;\n    const amount = typeof raw.amount === 'number' ? raw.amount : undefined;\n    const tx = asRecord(raw.transaction);\n    const transactionStatusCodeRaw = tx.statusCode ?? tx.StatusCode;\n    const transactionStatusCode =\n        typeof transactionStatusCodeRaw === 'number'\n            ? transactionStatusCodeRaw\n            : typeof transactionStatusCodeRaw === 'string' && transactionStatusCodeRaw.trim() !== ''\n                ? Number(transactionStatusCodeRaw)\n                : undefined;\n\n    const ok =\n        internalCode === 0 ||\n        (typeof internalDescription === 'string' && ['OK', 'VERIFIED'].includes(internalDescription.toUpperCase()));\n\n    const result = {\n        ok,\n        paid: false,\n        amount,\n        orderStatus,\n        transactionStatus,\n        transactionStatusCode: Number.isFinite(transactionStatusCode) ? transactionStatusCode : undefined,\n        internalCode,\n        internalDescription,\n        raw,\n        document: extractTakbullDocument(raw),\n    };\n    result.paid = isTakbullPaymentPaid(result);\n\n    const extracted = extractTokenFromValidated(raw);\n    if (extracted) {\n        result.token = extracted.token;\n        result.last4Digits = extracted.last4Digits;\n        result.expMonth = extracted.expMonth;\n        result.expYear = extracted.expYear;\n        result.cardBrand = extracted.cardBrand;\n    }\n\n    return result;\n}\n\nasync function chargeTakbullToken(input) {\n    assertBillingOperationsEnabled();\n    requirePositiveAmount(input);\n    const currency = input.currency.toUpperCase() === 'ILS' ? 'ILS' : input.currency.toUpperCase();\n    const body = {\n        order_reference: input.orderReference,\n        OrderTotalSum: input.amount,\n        Currency: currency,\n        Language: 'he',\n        DealType: 1,\n        PaymentMethodType: 3,\n        ...paymentDocumentOptions(input),\n        SaveToken: false,\n        MaxNumberOfPayments: 1,\n        IPNAddress: input.ipnAddress,\n        RedirectAddress: input.redirectAddress || input.ipnAddress,\n        CancelReturnAddress: input.cancelReturnAddress || input.ipnAddress,\n        CreditCard: { CardExternalToken: input.cardExternalToken },\n    };\n\n    if (input.purpose || body.CreateDocument) {\n        body.Products = [\n            {\n                SKU: String(input.orderReference).slice(0, 40),\n                ProductName: input.purpose || 'תשלום מנוי',\n                Description: input.purpose || 'תשלום מנוי',\n                Price: input.amount,\n                Quantity: 1,\n                CurrencyCode: currency,\n            },\n        ];\n    }\n\n    applyCustomer(body, input);\n\n    const res = await fetch(`${TAKBULL_API_BASE}/api/ExtranalAPI/ChargeToken`, {\n        method: 'POST',\n        headers: authHeaders(requireCreds(input.credentials)),\n        body: JSON.stringify(body),\n        signal: AbortSignal.timeout(20000),\n        redirect: 'error',\n    });\n\n    const raw = asRecord(await res.json().catch(() => ({})));\n    const internalCode =\n        typeof raw.internalCode === 'number'\n            ? raw.internalCode\n            : typeof raw.InternalCode === 'number'\n                ? raw.InternalCode\n                : null;\n    const internalDescription =\n        typeof raw.internalDescription === 'string'\n            ? raw.internalDescription\n            : typeof raw.InternalDescription === 'string'\n                ? raw.InternalDescription\n                : null;\n    const transactionInternalNumber =\n        pickStringField(raw, ['transactionInternalNumber', 'TransactionInternalNumber', 'transactionInternalId', 'TransactionInternalId']) ||\n        null;\n    const orderStatus = typeof raw.orderStatus === 'number' ? raw.orderStatus : null;\n\n    const ok = res.ok && internalCode === 0;\n    const definitiveFailure = !ok && await isConfirmedFailedTransaction(input, transactionInternalNumber);\n    return {\n        ok,\n        definitiveFailure,\n        internalCode,\n        internalDescription,\n        transactionInternalNumber,\n        orderStatus,\n        raw,\n        documentRequested: body.CreateDocument,\n        document: extractTakbullDocument(raw),\n        token: extractTokenFromValidated(raw),\n    };\n}\n\nconst {\n    getTakbullCredentialsFromEnv,\n    getTakbullMode,\n    resolveSetupAmountIls,\n} = require('./takbullCredentials');\n\nmodule.exports = {\n    TAKBULL_API_BASE,\n    TAKBULL_PAYMENT_GATEWAY,\n    paymentGatewayUrl,\n    isTakbullPaymentPaid,\n    extractTokenFromValidated,\n    extractTakbullDocument,\n    createTakbullPaymentPage,\n    validateTakbullNotification,\n    chargeTakbullToken,\n    getTakbullCredentialsFromEnv,\n    getTakbullMode,\n    resolveSetupAmountIls,\n    requireCreds,\n};\n", "backend/lib/payments/takbullCredentials.js": "/**\n * Takbull credential selection — never mix sandbox and production silently.\n *\n * Preferred .env layout:\n *   TAKBULL_MODE=prod|test\n *   PROD_TAKBULL_API_KEY=...\n *   PROD_TAKBULL_API_SECRET=...\n *   TEST_TAKBULL_API_KEY=...   (Takbull developer sandbox only)\n *   TEST_TAKBULL_API_SECRET=...\n *\n * Legacy (deprecated): TAKBULL_API_KEY + TAKBULL_API_SECRET\n */\n\nfunction readKeySecret(prefix) {\n    const apiKey = String(process.env[`${prefix}_API_KEY`] || '').trim();\n    const apiSecret = String(process.env[`${prefix}_API_SECRET`] || '').trim();\n    if (!apiKey || !apiSecret) return null;\n    return { apiKey, apiSecret };\n}\n\nfunction normalizeTakbullMode(raw) {\n    const v = String(raw || 'prod').trim().toLowerCase();\n    if (v === 'test' || v === 'sandbox' || v === 'dev') return 'test';\n    return 'prod';\n}\n\nfunction getTakbullMode() {\n    return normalizeTakbullMode(process.env.TAKBULL_MODE);\n}\n\nfunction getTakbullCredentialsFromEnv() {\n    const mode = getTakbullMode();\n    const named = mode === 'test'\n        ? readKeySecret('TEST_TAKBULL')\n        : readKeySecret('PROD_TAKBULL');\n    if (named) {\n        return { ...named, mode };\n    }\n\n    const legacy = readKeySecret('TAKBULL');\n    if (legacy) {\n        if (!global.__takbullLegacyCredWarned) {\n            global.__takbullLegacyCredWarned = true;\n            console.warn(\n                '[takbull] Using legacy TAKBULL_API_KEY/TAKBULL_API_SECRET. '\n                + 'Set TAKBULL_MODE plus PROD_TAKBULL_* and TEST_TAKBULL_* to avoid confusion.'\n            );\n        }\n        return { ...legacy, mode: 'legacy' };\n    }\n\n    return null;\n}\n\n/** One-time card verification charge (setup checkout), in ILS. */\nfunction resolveSetupAmountIls() {\n    const raw = process.env.BILLING_CARD_VERIFICATION_AMOUNT_ILS;\n    if (raw !== undefined && String(raw).trim() !== '') {\n        const n = Number(raw);\n        if (Number.isFinite(n) && n > 0) return n;\n    }\n    return 1;\n}\n\nmodule.exports = {\n    getTakbullMode,\n    getTakbullCredentialsFromEnv,\n    resolveSetupAmountIls,\n    normalizeTakbullMode,\n};\n", "backend/tests/hostedPaymentVerification.test.js": "'use strict';\nconst test = require('node:test');\nconst assert = require('node:assert/strict');\nconst { verifyHostedPayment, verifySignupPayment } = require('../lib/payments/verifySignupPayment');\n\nconst credentials = { apiKey: 'synthetic', apiSecret: 'synthetic' };\nconst order = {\n    uniqId: 'synthetic-order-id', order_reference: 'synthetic-subscription-20261025',\n    currency: 'ILS', orderTotalSum: 532.75, orderStatus: 3,\n    transactions: [{ transactionId: 'synthetic-transaction-id', status: 1, amount: 532.75 }],\n};\nconst transaction = {\n    transactionId: 'synthetic-transaction-id', amount: 532.75, currency: 'ILS',\n    status: 1, statusCode: 0, transactionType: 10, paymentMethod: 3,\n};\nfunction provider({ orderPatch, transactionPatch, failRead } = {}) {\n    const reads = [];\n    const fetcher = async (input, options) => {\n        const url = new URL(input);\n        assert.equal(url.origin, 'https://api.takbull.co.il');\n        assert.equal(options.redirect, 'error');\n        assert.equal(options.headers.API_Key, credentials.apiKey);\n        assert.equal(options.headers.API_Secret, credentials.apiSecret);\n        const isOrder = url.pathname.endsWith('/GetOrder');\n        reads.push(isOrder ? 'order' : 'transaction');\n        if (isOrder) assert.equal(url.searchParams.get('orderUniqId'), order.uniqId);\n        else assert.equal(url.searchParams.get('transactionInternalNumber'), transaction.transactionId);\n        return {\n            ok: failRead !== (isOrder ? 'order' : 'transaction'),\n            json: async () => isOrder ? { ...order, ...orderPatch } : { ...transaction, ...transactionPatch },\n        };\n    };\n    return { fetcher, reads };\n}\nconst verify = p => verifyHostedPayment(credentials, order.uniqId, order.order_reference, 532.75, p.fetcher);\n\ntest('hosted subscription verification binds the exact approved order and transaction without requiring a saved card', async () => {\n    const p = provider();\n    const result = await verify(p);\n    assert.deepEqual(result, { transactionId: transaction.transactionId, tokenInfo: null });\n    assert.deepEqual(p.reads, ['order', 'transaction']);\n});\n\ntest('foreign order identity, price, currency and ambiguous approved transaction are rejected before transaction lookup', async () => {\n    for (const orderPatch of [\n        { uniqId: 'foreign' }, { order_reference: 'foreign' }, { currency: 'USD' },\n        { orderTotalSum: 532 }, { orderStatus: 2 }, { transactions: [] },\n        { transactions: [{ transactionId: transaction.transactionId, status: 1, amount: 532 }] },\n        { transactions: [...order.transactions, { transactionId: 'second-approved', status: 1, amount: 532.75 }] },\n        { transactions: [...order.transactions, { transactionId: 'additional-wrong-amount', status: 1, amount: 1 }] },\n    ]) {\n        const p = provider({ orderPatch });\n        await assert.rejects(verify(p), /IDENTITY_MISMATCH/);\n        assert.deepEqual(p.reads, ['order']);\n    }\n});\n\ntest('callback-like approval cannot replace independent transaction amount, identity and card evidence', async () => {\n    for (const transactionPatch of [\n        { transactionId: 'foreign' }, { amount: 1 }, { currency: 'USD' },\n        { status: 0 }, { statusCode: null }, { statusCode: 1 },\n        { transactionType: 20 }, { paymentMethod: 2 },\n    ]) await assert.rejects(verify(provider({ transactionPatch })), /IDENTITY_MISMATCH/);\n});\n\ntest('unavailable provider reads and malformed expected prices never become verified receipts', async () => {\n    for (const failRead of ['order', 'transaction']) await assert.rejects(verify(provider({ failRead })), /PROVIDER_UNAVAILABLE/);\n    for (const amount of [0, -1, NaN, Infinity, '532.75']) {\n        const p = provider();\n        await assert.rejects(verifyHostedPayment(credentials, order.uniqId, order.order_reference, amount, p.fetcher), /VERIFICATION_REQUIRED/);\n        assert.equal(p.reads.length, 0);\n    }\n});\n\ntest('optional hosted token handling does not relax the one-shekel signup card-storage requirement', async () => {\n    const missingToken = provider({\n        orderPatch: { orderTotalSum: 1, transactions: [{ transactionId: transaction.transactionId, status: 1, amount: 1 }] },\n        transactionPatch: { amount: 1 },\n    });\n    await assert.rejects(verifySignupPayment(credentials, order.uniqId, order.order_reference, missingToken.fetcher), /TOKEN_REQUIRED/);\n});\n", "backend/tests/signupPaymentVerification.test.js": "const test=require('node:test'),assert=require('node:assert/strict');\nconst {verifySignupPayment,verifyChargedTransaction}=require('../lib/payments/verifySignupPayment');\nconst {addIsraelCalendarMonths}=require('../lib/billing/calendarMonths');\nconst credentials={apiKey:'synthetic',apiSecret:'synthetic'};\nconst order={uniqId:'order-id',order_reference:'signup-intent',currency:'ILS',orderTotalSum:1,orderStatus:3,transactions:[{transactionId:'transaction-id',status:1,amount:1}]};\nconst transaction={transactionId:'transaction-id',amount:1,currency:'ILS',status:1,statusCode:0,transactionType:10,paymentMethod:3,cardToken:'synthetic-card-token',last4DigitsCardNumber:'1234'};\nconst provider=(changes={})=>async url=>new Response(JSON.stringify(url.includes('/GetOrder')?{...order,...changes.order}:{...transaction,...changes.transaction}),{status:200,headers:{'Content-Type':'application/json'}});\ntest('signup uses authenticated order and card transaction, not callback amount/token',async()=>{\n const r=await verifySignupPayment(credentials,'order-id','signup-intent',provider());assert.equal(r.transactionId,'transaction-id');assert.equal(r.tokenInfo.token,'synthetic-card-token');\n});\ntest('signup rejects foreign, missing, wrong amount/currency/type and missing token evidence',async()=>{\n for(const patch of [{order:{uniqId:'foreign'}},{order:{order_reference:'foreign'}},{order:{currency:'USD'}},{order:{orderTotalSum:2}},{order:{orderStatus:2}},{order:{transactions:[]}},{transaction:{transactionId:'foreign'}},{transaction:{amount:2}},{transaction:{currency:'USD'}},{transaction:{status:0}},{transaction:{statusCode:null}},{transaction:{transactionType:20}},{transaction:{paymentMethod:2}},{transaction:{cardToken:null}}])await assert.rejects(verifySignupPayment(credentials,'order-id','signup-intent',provider(patch)));\n});\ntest('saved-token renewal requires exact independently read transaction evidence',async()=>{\n assert.equal(await verifyChargedTransaction(credentials,'transaction-id',1,provider()),true);\n for(const patch of [{amount:2},{currency:null},{statusCode:null},{transactionId:'foreign'},{paymentMethod:2}])await assert.rejects(verifyChargedTransaction(credentials,'transaction-id',1,provider({transaction:patch})));\n});\ntest('three calendar months use Israel local time and clamp month ends through DST',()=>{\n for(const [from,to] of [['2026-01-31T10:15:00Z','2026-04-30T09:15:00Z'],['2026-10-11T21:52:26Z','2027-01-11T22:52:26Z'],['2023-11-30T10:15:00Z','2024-02-29T10:15:00Z']])assert.equal(addIsraelCalendarMonths(new Date(from),3).toISOString(),new Date(to).toISOString());\n});\n", "backend/tests/takbullDocuments.test.js": "'use strict';\n\nconst test = require('node:test');\nconst assert = require('node:assert/strict');\nconst {\n    createTakbullPaymentPage,\n    chargeTakbullToken,\n    extractTakbullDocument,\n} = require('../lib/payments/takbullClient');\n\nconst input = {\n    credentials: { apiKey: 'synthetic-key', apiSecret: 'synthetic-secret' },\n    orderReference: 'synthetic-billing-order', amount: 1353, currency: 'ILS',\n    cardExternalToken: 'synthetic-card-token',\n    customerFullName: 'Synthetic Customer', customerEmail: 'synthetic@example.invalid', customerPhone: '0500000000',\n    customerAddress: { address1: 'Synthetic street 1', city: 'Synthetic City', country: 'IL', zip: '00000' },\n    ipnAddress: 'https://api.example.invalid/ipn', redirectAddress: 'https://app.example.invalid/return',\n    cancelReturnAddress: 'https://app.example.invalid/cancel', purpose: 'Synthetic monthly subscription',\n};\n\nfunction response(raw, status = 200) {\n    return { ok: status >= 200 && status < 300, status, json: async () => raw };\n}\n\nfunction intercept(t, fetcher) {\n    const oldFetch = global.fetch;\n    const oldType = process.env.TAKBULL_DOCUMENT_TYPE;\n    delete process.env.TAKBULL_DOCUMENT_TYPE;\n    global.fetch = fetcher;\n    t.after(() => {\n        global.fetch = oldFetch;\n        if (oldType === undefined) delete process.env.TAKBULL_DOCUMENT_TYPE;\n        else process.env.TAKBULL_DOCUMENT_TYPE = oldType;\n    });\n}\n\ntest('hosted checkout and saved-card charge request one provider-native document with recipient and amount', async t => {\n    const calls = [];\n    intercept(t, async (url, options) => {\n        const body = JSON.parse(options.body);\n        calls.push({ url, options, body });\n        return url.endsWith('/ChargeToken')\n            ? response({ internalCode: 0, transactionInternalNumber: 'synthetic-tx', documentId: 92, invoiceUniqId: 'synthetic-invoice', documentNumber: 40019 })\n            : response({ responseCode: 0, uniqId: 'synthetic-order' });\n    });\n    await createTakbullPaymentPage(input);\n    const charged = await chargeTakbullToken(input);\n    assert.equal(calls.length, 2, 'no separate document creation or delivery write');\n    for (const { body, options } of calls) {\n        assert.equal(body.CreateDocument, true);\n        assert.equal(body.DocumentType, undefined, 'preserve merchant document type and VAT settings');\n        assert.equal(body.Customer.Email, input.customerEmail);\n        assert.equal(body.Customer.CustomerFullName, input.customerFullName);\n        assert.deepEqual(body.Customer.Address, { Address1: 'Synthetic street 1', City: 'Synthetic City', Country: 'IL', Zip: '00000' });\n        assert.equal(body.OrderTotalSum, 1353);\n        assert.equal(body.Products[0].Price, 1353);\n        assert.equal(body.Products[0].Quantity, 1);\n        assert.equal(options.redirect, 'error');\n        assert.ok(options.signal);\n    }\n    assert.equal(charged.ok, true);\n    assert.equal(charged.definitiveFailure, false);\n    assert.deepEqual(charged.document, { created: true, id: '92', uniqId: 'synthetic-invoice', number: '40019', deliveryStatus: 'unknown' });\n});\n\ntest('1 ILS card verification remains a real payment document and gets a line item without a supplied purpose', async t => {\n    let body;\n    intercept(t, async (_url, options) => {\n        body = JSON.parse(options.body);\n        return response({ responseCode: 0, uniqId: 'synthetic-setup' });\n    });\n    await createTakbullPaymentPage({ ...input, amount: 1, purpose: undefined });\n    assert.equal(body.CreateDocument, true);\n    assert.equal(body.OrderTotalSum, 1);\n    assert.equal(body.Products[0].Price, 1);\n    assert.ok(body.Products[0].Description);\n});\n\ntest('explicit receipt type or existing configured type is validated before any payment request', async t => {\n    const bodies = [];\n    intercept(t, async (_url, options) => {\n        bodies.push(JSON.parse(options.body));\n        return response({ internalCode: 0, transactionInternalNumber: 'synthetic-tx' });\n    });\n    process.env.TAKBULL_DOCUMENT_TYPE = '400';\n    await chargeTakbullToken(input);\n    await chargeTakbullToken({ ...input, documentType: 320 });\n    await chargeTakbullToken({ ...input, createDocument: false });\n    assert.deepEqual(bodies.map(b => [b.CreateDocument, b.DocumentType]), [[true, 400], [true, 320], [false, undefined]]);\n    for (const invalid of [305, 330, 0, 'garbage']) {\n        await assert.rejects(chargeTakbullToken({ ...input, documentType: invalid }), /TAKBULL_DOCUMENT_TYPE/);\n    }\n    assert.equal(bodies.length, 3);\n});\n\ntest('zero, negative, or invalid amount never reaches a payment/document operation', async t => {\n    let calls = 0;\n    intercept(t, async () => { calls++; throw Error('must not dispatch'); });\n    for (const amount of [0, -1, NaN, Infinity, 'invalid']) {\n        await assert.rejects(chargeTakbullToken({ ...input, amount }), /amount must be positive/);\n        await assert.rejects(createTakbullPaymentPage({ ...input, amount }), /amount must be positive/);\n    }\n    assert.equal(calls, 0);\n});\n\ntest('timeout is not retried and cannot trigger a separate document operation', async t => {\n    let calls = 0;\n    intercept(t, async () => { calls++; throw Error('synthetic timeout after provider accepted request'); });\n    await assert.rejects(chargeTakbullToken(input), /synthetic timeout/);\n    assert.equal(calls, 1);\n});\n\ntest('HTTP errors, malformed responses, and unbound provider errors remain uncertain', async t => {\n    const replies = [response({}, 503), { ok: true, status: 200, json: async () => { throw Error('bad JSON'); } }, response({ internalCode: 62, orderStatus: 1 })];\n    let calls = 0;\n    intercept(t, async () => { calls++; return replies.shift(); });\n    for (let i = 0; i < 3; i++) {\n        const result = await chargeTakbullToken(input);\n        assert.equal(result.ok, false);\n        assert.equal(result.definitiveFailure, false);\n        assert.equal(result.document.created, null);\n    }\n    assert.equal(calls, 3, 'no retry or separate document creation');\n});\n\ntest('document error after an approved charge is uncertain and never a safe new-charge signal', async t => {\n    const calls = [];\n    intercept(t, async (url, options) => {\n        calls.push([url, options.method]);\n        if (url.endsWith('/ChargeToken')) return response({ internalCode: 99, transactionInternalNumber: 'synthetic-tx' });\n        return response({ transactionId: 'synthetic-tx', amount: 1353, currency: 'ILS', transactionType: 10, paymentMethod: 3, status: 1, statusCode: 0, isDocumentCreated: false });\n    });\n    const result = await chargeTakbullToken(input);\n    assert.equal(result.ok, false);\n    assert.equal(result.definitiveFailure, false);\n    assert.equal(calls.length, 2);\n    assert.ok(calls[1][0].includes('/GetTransaction?transactionInternalNumber=synthetic-tx'));\n    assert.equal(calls[1][1], undefined, 'reconciliation is read-only');\n});\n\ntest('only a matching terminal failed card charge permits retry; mismatches and unavailable reads remain uncertain', async t => {\n    const failed = { transactionId: 'synthetic-tx', amount: 1353, currency: 'ILS', transactionType: 10, paymentMethod: 3, status: 2, statusCode: 5 };\n    let current = failed;\n    intercept(t, async url => {\n        if (url.endsWith('/ChargeToken')) return response({ internalCode: 5, transactionInternalNumber: 'synthetic-tx' });\n        if (current === null) throw Error('synthetic provider unavailable');\n        return response(current);\n    });\n    for (const status of [2, 6]) {\n        current = { ...failed, status };\n        assert.equal((await chargeTakbullToken(input)).definitiveFailure, true);\n    }\n    for (const patch of [{ transactionId: 'different' }, { amount: 1 }, { currency: 'USD' }, { transactionType: 20 }, { paymentMethod: 1 }, { status: 1 }, { status: 4 }, { statusCode: 0 }, { statusCode: null }]) {\n        current = { ...failed, ...patch };\n        assert.equal((await chargeTakbullToken(input)).definitiveFailure, false, JSON.stringify(patch));\n    }\n    current = null;\n    assert.equal((await chargeTakbullToken(input)).definitiveFailure, false);\n});\n\ntest('document reference does not assert email delivery or mistake zero document ID for a receipt', () => {\n    assert.deepEqual(extractTakbullDocument({ documentId: 0 }), { created: null, id: null, uniqId: null, number: null, deliveryStatus: 'unknown' });\n    assert.equal(extractTakbullDocument({ isDocumentCreated: false }).created, false);\n    assert.equal(extractTakbullDocument({ isDocumentCreated: true }).created, true);\n});\n", "backend/tests/pricingPackage.test.js": "const test = require('node:test');\nconst assert = require('node:assert/strict');\n\nconst {\n    evaluatePackageChange,\n    disabledOptionsForUsage,\n    resolvePricingLineItems,\n    quotasForPackage,\n    recommendCheapestPackage,\n    RESOURCE_SMS_MONTHLY_QUOTA,\n    yearlyTotalIls,\n    yearlySavingsIls,\n    normalizeBillingInterval,\n} = require('../lib/billing/pricingPackage');\n\ntest('evaluatePackageChange blocks cheaper signing when documents exceed pack', () => {\n    const ev = evaluatePackageChange({\n        current: { platformId: 'site_app', resourceId: 'pro', signingId: '1500' },\n        next: { platformId: 'site_app', resourceId: 'pro', signingId: '500' },\n        usage: { documents: { createdThisMonth: 600 }, seats: { used: 1 }, storage: { bytesTotal: 0 } },\n    });\n    assert.equal(ev.allowed, false);\n    assert.ok(ev.blocks.some((b) => b.field === 'signingId'));\n});\n\ntest('evaluatePackageChange allows upgrade even when over current quota', () => {\n    const ev = evaluatePackageChange({\n        current: { platformId: 'site_app', resourceId: 'basic', signingId: '500' },\n        next: { platformId: 'site_app', resourceId: 'pro', signingId: '1500' },\n        usage: { documents: { createdThisMonth: 600 }, seats: { used: 3 }, storage: { bytesTotal: 0 } },\n    });\n    assert.equal(ev.allowed, true);\n    assert.equal(ev.priceIncreased, true);\n});\n\ntest('evaluatePackageChange blocks platform downgrade from site_app', () => {\n    const ev = evaluatePackageChange({\n        current: { platformId: 'site_app', resourceId: 'pro', signingId: '500' },\n        next: { platformId: 'site', resourceId: 'pro', signingId: '500' },\n        usage: { documents: { createdThisMonth: 0 }, seats: { used: 1 }, storage: { bytesTotal: 0 } },\n    });\n    assert.equal(ev.allowed, false);\n    assert.ok(ev.blocks.some((b) => b.field === 'platformId'));\n});\n\ntest('evaluatePackageChange blocks resource downgrade when seats exceed', () => {\n    const ev = evaluatePackageChange({\n        current: { platformId: 'site_app', resourceId: 'pro', signingId: '500' },\n        next: { platformId: 'site_app', resourceId: 'basic', signingId: '500' },\n        usage: { documents: { createdThisMonth: 0 }, seats: { used: 4 }, storage: { bytesTotal: 0 } },\n    });\n    assert.equal(ev.allowed, false);\n    assert.ok(ev.blocks.some((b) => b.field === 'resourceId'));\n});\n\ntest('disabledOptionsForUsage marks cheaper signing packs', () => {\n    const disabled = disabledOptionsForUsage({\n        current: { platformId: 'site_app', resourceId: 'pro', signingId: '1500' },\n        usage: { documents: { createdThisMonth: 600 }, seats: { used: 1 }, storage: { bytesTotal: 0 } },\n    });\n    assert.ok(disabled.signingIds.includes('500'));\n    assert.ok(!disabled.signingIds.includes('1500'));\n});\n\ntest('resolvePricingLineItems default site_app + pro + 500 totals 972', () => {\n    const resolved = resolvePricingLineItems({\n        platformId: 'site_app',\n        resourceId: 'pro',\n        signingId: '500',\n    });\n    assert.equal(resolved.total, 296 + 296 + 211 + 169);\n    assert.equal(resolved.displayName, 'פרו · אתר + אפליקציה · 500 חתימות');\n    const q = quotasForPackage(resolved);\n    assert.equal(q.usersQuota, 5);\n    assert.equal(q.storageMbQuota, 1024);\n    assert.equal(q.documentsMonthlyQuota, 500);\n    assert.equal(q.otpSmsMonthlyQuota, 2000);\n});\n\ntest('enterprise SMS monthly quota is 5000 not unlimited', () => {\n    assert.equal(RESOURCE_SMS_MONTHLY_QUOTA.enterprise, 5000);\n    const q = quotasForPackage({ resourceId: 'enterprise', signingId: '500' });\n    assert.equal(q.otpSmsMonthlyQuota, 5000);\n});\n\ntest('recommendCheapestPackage: MelamedLaw-shaped usage needs enterprise 1353', () => {\n    const rec = recommendCheapestPackage({\n        current: { platformId: 'site_app', resourceId: 'pro', signingId: '500' },\n        usage: {\n            documents: { createdThisMonth: 74 },\n            seats: { used: 8 },\n            storage: { bytesTotal: 280.4 * 1024 * 1024 },\n            sms: { sentThisMonth: 421 },\n        },\n    });\n    assert.equal(rec.recommended.platformId, 'site_app');\n    assert.equal(rec.recommended.resourceId, 'enterprise');\n    assert.equal(rec.recommended.signingId, '500');\n    assert.equal(rec.recommended.total, 296 + 296 + 592 + 169);\n    assert.equal(rec.changed, true);\n});\n\ntest('recommendCheapestPackage: MorLevi-shaped usage fits basic 845', () => {\n    const rec = recommendCheapestPackage({\n        current: { platformId: 'site_app', resourceId: 'pro', signingId: '500' },\n        usage: {\n            documents: { createdThisMonth: 0 },\n            seats: { used: 0 },\n            storage: { bytesTotal: 0 },\n            sms: { sentThisMonth: 10 },\n        },\n    });\n    assert.equal(rec.recommended.platformId, 'site_app');\n    assert.equal(rec.recommended.resourceId, 'basic');\n    assert.equal(rec.recommended.signingId, '500');\n    assert.equal(rec.recommended.total, 296 + 296 + 84 + 169);\n    assert.equal(rec.changed, true);\n});\n\ntest('recommendCheapestPackage: SMS above pro cap 2000 needs enterprise', () => {\n    const rec = recommendCheapestPackage({\n        current: { platformId: 'site_app', resourceId: 'pro', signingId: '500' },\n        usage: {\n            documents: { createdThisMonth: 0 },\n            seats: { used: 1 },\n            storage: { bytesTotal: 0 },\n            sms: { sentThisMonth: 2001 },\n        },\n    });\n    assert.equal(rec.recommended.resourceId, 'enterprise');\n    assert.equal(rec.recommended.total, 296 + 296 + 592 + 169);\n});\n\ntest('yearly billing is 10% off 12 months, rounded', () => {\n    assert.equal(normalizeBillingInterval('yearly'), 'yearly');\n    assert.equal(normalizeBillingInterval('YEARLY'), 'yearly');\n    assert.equal(normalizeBillingInterval('monthly'), 'monthly');\n    assert.equal(normalizeBillingInterval(null), 'monthly');\n\n    assert.equal(yearlyTotalIls(1353), 14612);\n    assert.equal(yearlySavingsIls(1353), 1624);\n    assert.equal(yearlyTotalIls(972), 10498);\n    assert.equal(yearlySavingsIls(972), 1166);\n    assert.equal(yearlyTotalIls(845), 9126);\n    assert.equal(yearlySavingsIls(845), 1014);\n\n    const enterprise = resolvePricingLineItems({\n        platformId: 'site_app',\n        resourceId: 'enterprise',\n        signingId: '500',\n    });\n    assert.equal(enterprise.total, 1353);\n    assert.equal(enterprise.yearlyTotal, 14612);\n    assert.equal(enterprise.yearlySavings, 1624);\n});\n\n test('new package choices reject a platform-free contract even from legacy none', () => {\n const ev=evaluatePackageChange({current:{platformId:'none',resourceId:'basic',signingId:'none'},next:{platformId:'none',resourceId:'basic',signingId:'none'},usage:{}});\n assert.equal(ev.allowed,false); assert.ok(ev.blocks.some(b=>b.field==='platformId'));\n });\n", "backend/tests/signupQuote.test.js": "'use strict';\nconst test = require('node:test');\nconst assert = require('node:assert/strict');\nconst { PRICING } = require('../lib/billing/pricingPackage');\nconst { quoteSignup, renewalAmount, CONSENT_VERSION } = require('../lib/billing/signupQuote');\n\ntest('all 90 allowed signup choices use final prices and the existing annual discount', () => {\n    let combinations = 0;\n    for (const platform of PRICING.platforms.filter(p => p.id !== 'none')) for (const resource of PRICING.resources) for (const signing of PRICING.signing) for (const billingInterval of ['monthly', 'yearly']) {\n        const q = quoteSignup({ platformId: platform.id, resourceId: resource.id, signingId: signing.id, billingInterval });\n        const monthly = 296 + platform.amount + resource.amount + signing.amount;\n        const expectedNet = billingInterval === 'yearly' ? Math.round(monthly * 12 * 0.9) : monthly;\n        assert.equal(q.netAmountIls, expectedNet);\n        assert.equal(q.vatPercent, 0);\n        assert.equal(Math.round(q.recurringAmountIls * 100), Math.round(expectedNet * 100));\n        combinations++;\n    }\n    assert.equal(combinations, 90);\n});\ntest('website plus basic resources costs ₪532 final; historical system-only contracts remain unchanged', () => {\n    const q = quoteSignup({ platformId: 'site', resourceId: 'basic', signingId: 'none', billingInterval: 'monthly' });\n    assert.equal(q.recurringAmountIls, 532);\n    const account = { billing_interval: 'monthly', price_monthly_ils: 380 };\n    const newAgreement = { consent_version: CONSENT_VERSION, recurring_amount_ils: '532.00' };\n    assert.equal(renewalAmount({ billing_interval: 'monthly', price_monthly_ils: 532 }, newAgreement), 532);\n    assert.equal(renewalAmount({}, newAgreement), 532);\n    assert.equal(renewalAmount(account, { consent_version: 'signup-1ils-3months-v1' }), 380);\n    assert.equal(renewalAmount({ ...account, billing_interval: 'yearly' }, { consent_version: 'signup-1ils-3months-v1' }), 4104);\n});\ntest('accepted plan changes use the agreed billing row, not an obsolete signup or live catalogue price', () => {\n    const agreement = { consent_version: CONSENT_VERSION, recurring_amount_ils: '532.00' };\n    assert.equal(renewalAmount({ billing_interval: 'monthly', price_monthly_ils: '700' }, agreement), 700);\n    assert.equal(renewalAmount({ billing_interval: 'yearly', price_monthly_ils: '700' }, agreement), 7560);\n});\ntest('invalid choices and missing new contract charge fail closed', () => {\n    const valid = { platformId: 'site', resourceId: 'basic', signingId: 'none', billingInterval: 'monthly' };\n    assert.throws(() => quoteSignup({ ...valid, platformId: 'none' }), { code: 'INVALID_PACKAGE' });\n    for (const key of Object.keys(valid)) {\n        assert.throws(() => quoteSignup({ ...valid, [key]: 'untrusted' }), { code: 'INVALID_PACKAGE' });\n    }\n    for (const amount of [null, 0, -1, 'NaN']) assert.throws(() => renewalAmount({}, { consent_version: CONSENT_VERSION, recurring_amount_ils: amount }));\n});\n"};

